    {
      "id": "E9536f10a4ae90cb9",
      "pertinente": true,
      "tipo": "explicacao_tecnica",
      "achados": [
        {
          "proposicao": "A seletividade do adsorvente influencia qual componente do ar é preferencialmente separado: a fonte indica que certas zeólitas adsorvem preferencialmente nitrogênio, enquanto em peneiras moleculares de carbono o oxigênio difunde mais rapidamente que o nitrogênio.",
          "trechos": [
            "E9536f10a4ae90cb9:0:700"
          ],
          "condicoes": [
            "separação de ar por adsorção",
            "comparação entre zeólitas e peneiras moleculares de carbono"
          ],
          "limites": [
            "os valores numéricos de pureza e de razão de difusão estão apagados",
            "o trecho não fornece critério quantitativo fechado para selecionar o adsorvente em uma instalação específica"
          ]
        },
        {
          "proposicao": "Na produção de oxigênio por PSA com zeólita, o nitrogênio do ar é descrito como adsorvido em sítios reativos nos poros, enquanto o oxigênio atravessa o leito e pode ser produzido com alta pureza.",
          "trechos": [
            "E9536f10a4ae90cb9:700:1400"
          ],
          "condicoes": [
            "uso de peneira molecular de zeólita",
            "aplicação voltada à produção de oxigênio a partir do ar"
          ],
          "limites": [
            "o enunciado trata do caso de produção de oxigênio, não de nitrogênio para inertização",
            "as purezas e faixas operacionais citadas no trecho estão apagadas"
          ]
        },
        {
          "proposicao": "A fonte aponta heterogeneidade de superfície dos adsorventes usuais como fator complicador, embora afirme que o desenvolvimento do PSA para separação de gases com esses materiais tem sido eficiente.",
          "trechos": [
            "E9536f10a4ae90cb9:700:1400",
            "E9536f10a4ae90cb9:1400:2098"
          ],
          "condicoes": [
            "uso de adsorventes como zeólitas, carvões ativados, aluminas e sílica gel"
          ],
          "limites": [
            "a eficiência mencionada é uma caracterização geral da fonte, sem métricas visíveis no excerto",
            "o trecho também afirma que ainda há necessidade de pesquisas, portanto não elimina incertezas técnicas"
          ]
        }
      ]
    },
    {
      "id": "E0f8103ddc3e15435",
      "pertinente": true,
      "tipo": "explicacao_tecnica",
      "achados": [
        {
          "proposicao": "A fonte apresenta o PSA como tecnologia de separação e purificação de misturas gasosas em que componentes são adsorvidos seletivamente em materiais micro ou mesoporosos sob alta pressão no interior de uma coluna, produzindo um gás de maior pureza.",
          "trechos": [
            "E0f8103ddc3e15435:0:699",
            "E0f8103ddc3e15435:699:1396"
          ],
          "condicoes": [
            "mistura gasosa alimentada a uma coluna com material poroso",
            "operação baseada em adsorção seletiva"
          ],
          "limites": [
            "o trecho é introdutório e não detalha ciclo, controle, purga ou desempenho quantitativo",
            "não traz critérios operacionais específicos para FPSO"
          ]
        },
        {
          "proposicao": "No contexto do estudo descrito, uma zeólita comercial tipo X é proposta para adsorver nitrogênio do ar com o objetivo de enriquecer o ar em oxigênio usando PSA.",
          "trechos": [
            "E0f8103ddc3e15435:699:1396",
            "E0f8103ddc3e15435:1396:2094"
          ],
          "condicoes": [
            "escopo do trabalho citado na fonte",
            "uso de zeólita sintética comercial identificada como tipo X"
          ],
          "limites": [
            "trata-se de proposta e objetivo de pesquisa, não de comprovação de desempenho no excerto",
            "a aplicação descrita é enriquecimento de oxigênio, não geração de nitrogênio para inertização"
          ]
        }
      ]
    },
    {
      "id": "E539431e980b89520",
      "pertinente": true,
      "tipo": "explicacao_tecnica",
      "achados": [
        {
          "proposicao": "A fonte descreve a separação de ar como processo integral a muitas plantas industriais, produzindo tipicamente nitrogênio, oxigênio e argônio a partir de ar atmosférico e energia elétrica.",
          "trechos": [
            "E539431e980b89520:0:693"
          ],
          "condicoes": [
            "unidades de separação de ar"
          ],
          "limites": [
            "não diferencia, no excerto, as condições específicas de cada tecnologia de separação",
            "não apresenta requisitos de armazenamento ou distribuição de nitrogênio"
          ]
        },
        {
          "proposicao": "A fonte afirma que a separação do ar é intensiva em consumo de energia e relaciona a redução desse consumo a avanços de concepção e operação do processo, melhorias de fabricação, renovação de equipamentos, controle regulatório e avançado e integrações mássica e energética.",
          "trechos": [
            "E539431e980b89520:693:1390",
            "E539431e980b89520:1390:2083"
          ],
          "condicoes": [
            "contexto geral de plantas de separação de ar"
          ],
          "limites": [
            "o trecho não quantifica ganhos energéticos",
            "não atribui esses ganhos exclusivamente a PSA ou membranas"
          ]
        },
        {
          "proposicao": "Entre os processos citados para separação do ar, a fonte inclui destilação criogênica, PSA, absorção, membranas poliméricas e membranas de transporte de íons.",
          "trechos": [
            "E539431e980b89520:1390:2083",
            "E539431e980b89520:2083:2294"
          ],
          "condicoes": [
            "comparação geral de tecnologias de separação de ar"
          ],
          "limites": [
            "o trecho recuperado não apresenta critérios de escolha por pureza, capacidade ou aplicação",
            "a parte final está truncada"
          ]
        }
      ]
    },
    {
      "id": "E6e581be572edc861",
      "pertinente": true,
      "tipo": "explicacao_tecnica",
      "achados": [
        {
          "proposicao": "A fonte apresenta o PSA como tecnologia comumente utilizada para purificação de gases, incluindo separação de oxigênio ou nitrogênio do ar e purificação de hidrogênio de correntes oriundas de reforma catalítica de hidrocarbonetos.",
          "trechos": [
            "E6e581be572edc861:692:1385"
          ],
          "condicoes": [
            "contexto geral de purificação e separação gasosa"
          ],
          "limites": [
            "o excerto não delimita faixas de pureza, capacidade ou consumo para cada aplicação",
            "parte do contexto da fonte é purificação de hidrogênio, não inertização em FPSO"
          ]
        },
        {
          "proposicao": "No PSA, uma mistura gasosa é introduzida em leito adsorvente sob pressão elevada, e o sólido adsorve seletivamente certos componentes, permitindo que o componente menos adsorvido atravesse o leito como gás purificado.",
          "trechos": [
            "E6e581be572edc861:1385:2077"
          ],
          "condicoes": [
            "presença de leito adsorvente seletivo",
            "alimentação em pressão elevada"
          ],
          "limites": [
            "a fonte não detalha sequência de ciclo, purga ou estratégia de controle neste trecho",
            "não informa desempenho quantitativo"
          ]
        },
        {
          "proposicao": "A fonte distingue dois princípios de separação em adsorventes sólidos: adsorção de superfície por interação química preferencial e seletividade de tamanho em sólidos porosos.",
          "trechos": [
            "E6e581be572edc861:1385:2077",
            "E6e581be572edc861:2077:2152"
          ],
          "condicoes": [
            "separação de componentes de mistura gasosa com material sólido"
          ],
          "limites": [
            "o trecho final está truncado",
            "não vincula quantitativamente cada princípio a uma aplicação específica de geração de nitrogênio"
          ]
        }
      ]
    },
    {
      "id": "E2581ad46533b39de",
      "pertinente": true,
      "tipo": "resultado_experimental",
      "achados": [
        {
          "proposicao": "A fonte relata que a purga removeu o nitrogênio do duto e foi mantida com o objetivo adicional de volatilizar água líquida e remover umidade pelo FPSO.",
          "trechos": [
            "E2581ad46533b39de:0:698"
          ],
          "condicoes": [
            "procedimento de purga em gasoduto associado a FPSO",
            "interpretação operacional baseada no comportamento de pressão e cromatografia"
          ],
          "limites": [
            "o trecho trata de purga operacional em duto, não de geração de nitrogênio por PSA ou membranas",
            "não informa vazões, pressões, tempos ou critérios universais de encerramento da purga"
          ]
        },
        {
          "proposicao": "Durante a continuidade da despressurização, a fonte associa quedas e aumentos rápidos de pressão à provável formação de novo bloqueio, utilizando o perfil de pressão como evidência operacional.",
          "trechos": [
            "E2581ad46533b39de:698:1394"
          ],
          "condicoes": [
            "evento específico de purga/despressurização do sistema descrito"
          ],
          "limites": [
            "a própria fonte trata a interpretação como provável, não definitiva",
            "o comportamento observado depende da configuração específica do trecho flexível e do sistema analisado"
          ]
        },
        {
          "proposicao": "Após purga contínua prolongada, com aproximadamente quatro trocas de inventário do duto, o início da exportação ocorreu sem indícios de bloqueio ou pressão anormal, o que a fonte usa como evidência de eficácia do procedimento adotado para inibição de água livre no duto.",
          "trechos": [
            "E2581ad46533b39de:1394:2094"
          ],
          "condicoes": [
            "caso operacional específico descrito pela fonte"
          ],
          "limites": [
            "resultado empírico de um caso, não regra geral para todos os dutos ou FPSOs",
            "o foco é mitigação operacional de bloqueio/água livre, não pureza de nitrogênio ou especificação de inertização"
          ]
        }
      ]
    },
